import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.Ky-Ipuyb.js";const p=JSON.parse('{"title":"ImGui API guide","description":"","frontmatter":{"lang":"en","sourcePath":"docs/imgui/api.md"},"headers":[],"relativePath":"imgui/api.md","filePath":"imgui/api.md"}'),o={name:"imgui/api.md"};function d(n,e,c,s,l,u){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="imgui-api-guide" tabindex="-1">ImGui API guide <a class="header-anchor" href="#imgui-api-guide" aria-label="Permalink to &quot;ImGui API guide&quot;">​</a></h1><p>Use the <a href="/reference/imgui/" target="_self">API reference</a> to confirm an argument or return value after following the task-oriented guides. Its summaries identify operations; detail pages contain usage notes, parameters, return values and native lifetime restrictions.</p><h2 id="find-the-right-namespace" tabindex="-1">Find the right namespace <a class="header-anchor" href="#find-the-right-namespace" aria-label="Permalink to &quot;Find the right namespace&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task</th><th>Entry point</th><th>Tutorial</th></tr></thead><tbody><tr><td>Integrate a native window</td><td><code>SFML.Init</code>, <code>ProcessEvent</code>, <code>Update</code>, <code>Render</code>, <code>Shutdown</code></td><td><a href="/imgui/getting-started">Quick start</a></td></tr><tr><td>Declare a control</td><td><code>ImGui.Button</code>, <code>Checkbox</code>, <code>SliderFloatEx</code></td><td><a href="/imgui/widgets">Widgets</a></td></tr><tr><td>Organize a panel</td><td><code>BeginChild</code>, <code>BeginTable</code>, menu and popup functions</td><td><a href="/imgui/layout">Layout</a></td></tr><tr><td>Edit UTF-8 or supply callbacks</td><td><code>InputTextEx</code>, <code>ListBoxCallbackEx</code>, <code>PlotLinesCallbackEx</code></td><td><a href="/imgui/callbacks">Callbacks</a></td></tr><tr><td>Load fonts or edit style</td><td>Top-level <code>getFontAtlas</code>, <code>getStyleColors</code>; <code>SFML.GetStyle</code></td><td><a href="/imgui/fonts">Fonts</a></td></tr><tr><td>Draw primitives or switch windows</td><td><code>ImGui.GetWindowDrawList</code>, <code>SFML.SetCurrentWindow</code></td><td><a href="/imgui/rendering">Rendering</a></td></tr></tbody></table><h2 id="read-a-signature-as-a-javascript-contract" tabindex="-1">Read a signature as a JavaScript contract <a class="header-anchor" href="#read-a-signature-as-a-javascript-contract" aria-label="Permalink to &quot;Read a signature as a JavaScript contract&quot;">​</a></h2><p>For example, <a href="/reference/imgui/functions/ImGui.SliderFloatEx.html" target="_self">SliderFloatEx</a> accepts a writable <code>Float32Array</code>, two numeric bounds, a format string and flags. Its boolean return reports an edit; the current value is in the array. The native parameter name does not make a JavaScript number writable.</p><p>Overload names are explicit. <code>Button</code> is the default-size form; <code>ButtonEx</code> accepts a size. <code>PushStyleVar</code> takes a scalar; <code>PushStyleVarVec2</code> takes a vector. <code>Ex</code> does not universally mean “callback”: inspect each signature rather than inferring parameters from its suffix.</p><p><code>ImVec2Like</code> accepts supported vector values such as <code>[ x, y ]</code> or <code>{ x, y }</code>. A pointer to editable numeric data instead requires the typed array documented by that function. Struct handles, such as <code>ImGuiInputTextCallbackData</code>, are opaque branded objects returned by the binding. Texture IDs and raw pointer arguments use <code>bigint</code>; they are not interchangeable with struct handles. Never construct either from guessed addresses.</p><p><code>ImGui.GetIO()</code> and <code>ImGui.GetStyle()</code> return native handles. <code>SFML.GetIO()</code> and <code>SFML.GetStyle()</code> provide convenient writable field views for the currently selected window. A helper that accepts a handle cannot be given the convenience view instead.</p><h2 id="check-these-details-before-calling" tabindex="-1">Check these details before calling <a class="header-anchor" href="#check-these-details-before-calling" aria-label="Permalink to &quot;Check these details before calling&quot;">​</a></h2><ol><li>Whether the operation requires an initialized context, an active frame or a visible parent window.</li><li>Whether an argument is copied, modified in place or borrowed.</li><li>Whether optional <code>null</code> disables a feature, such as a window close button.</li><li>Whether a boolean means activation, content changed, selection, or visibility.</li><li>Which matching End/Pop operation is required and under which condition.</li><li>How long returned handles and views remain usable.</li></ol><p>The source declarations are useful for TypeScript tooling and implementation inspection: <a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-imgui/src/index.ts" target="_blank" rel="noreferrer">package exports</a>, <a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-imgui/src/sfml.ts" target="_blank" rel="noreferrer">SFML integration</a>, <a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-imgui/src/imgui/index.ts" target="_blank" rel="noreferrer">ImGui modules</a>.</p><p>API descriptions live beside those declarations, with English, Chinese, Japanese and Korean summaries and details. TypeDoc reads them directly. When reporting a documentation problem, include the exact function, language, expected JavaScript call and observed result.</p>',13)])])}const m=t(o,[["render",d]]);export{p as __pageData,m as default};
